#include <iostream>
#include <queue>
#include <vector>
#include <algorithm>
using namespace std;

const int MAXN = 25;
const int MAXID = 505;
const int INF = 1000000007;
const int SRC = 501;
const int SNK = 502;

char gridA[MAXN][MAXN], gridB[MAXN][MAXN];
int distZ[MAXN][MAXN];
int distPair[MAXID][MAXID];

int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};

struct Edge { int to, cap, flow, next; };
vector<Edge> edges;
vector<int> headNode(MAXID, -1);
int depth[MAXID], seen[MAXID], parentEdge[MAXID];
int answer = 0;

inline void addEdge(int u, int v, int cap) {
    int idx = (int)edges.size();
    edges.push_back({v, cap, 0, headNode[u]});
    headNode[u] = idx;
    edges.push_back({u, 0, 0, headNode[v]});
    headNode[v] = idx + 1;
}

inline bool bfsLevel() {
    queue<int> qu;
    for (int i = 0; i <= SNK; i++) seen[i] = depth[i] = 0;
    qu.push(SRC);
    seen[SRC] = 1;
    depth[SRC] = 1;
    while (!qu.empty()) {
        int x = qu.front(); qu.pop();
        for (int i = headNode[x]; i != -1; i = edges[i].next) {
            int y = edges[i].to;
            if (!seen[y] && edges[i].flow < edges[i].cap) {
                parentEdge[y] = i;
                seen[y] = 1;
                depth[y] = depth[x] + 1;
                qu.push(y);
                if (y == SNK) return true;
            }
        }
    }
    return false;
}

inline int sendFlow(int x, int now) {
    if (x == SNK || !now) return now;
    int rem = now;
    for (int i = headNode[x]; i != -1; i = edges[i].next) {
        int y = edges[i].to;
        if (edges[i].cap > edges[i].flow && depth[y] == depth[x] + 1) {
            int pushed = sendFlow(y, min(rem, edges[i].cap - edges[i].flow));
            if (!pushed) depth[y] = 0;
            edges[i].flow += pushed;
            edges[i ^ 1].flow -= pushed;
            rem -= pushed;
            if (rem == 0) break;
        }
    }
    return now - rem;
}

inline void dinic() {
    while (bfsLevel()) answer += sendFlow(SRC, INF);
}

int main() {
    int n, timeLimit;
    cin >> n >> timeLimit;
    headNode.assign(MAXID, -1);
    edges.clear();

    queue<int> q;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            distZ[i][j] = 10000;
            cin >> gridA[i][j];
            int startId = (i - 1) * n + j;
            if (gridA[i][j] == 'Z') {
                q.push(startId);
                distZ[i][j] = 0;
            }
            if (gridA[i][j] <= '9')
                addEdge(SRC, startId, gridA[i][j] - '0');
        }
    }

    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int x = (cur - 1) / n + 1;
        int y = (cur - 1) % n + 1;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx > 0 && ny > 0 && nx <= n && ny <= n && gridA[nx][ny] <= '9' &&
                distZ[nx][ny] > distZ[x][y] + 1) {
                distZ[nx][ny] = distZ[x][y] + 1;
                q.push((nx - 1) * n + ny);
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (gridA[i][j] > '9') continue;
            int startId = (i - 1) * n + j;
            for (int k = 1; k <= n; k++)
                for (int l = 1; l <= n; l++)
                    distPair[startId][(k - 1) * n + l] = 10000;
            q.push(startId);
            distPair[startId][startId] = 0;
            while (!q.empty()) {
                int cur = q.front(); q.pop();
                int x = (cur - 1) / n + 1;
                int y = (cur - 1) % n + 1;
                for (int f = 0; f < 4; f++) {
                    int nx = x + dx[f], ny = y + dy[f];
                    if (nx > 0 && ny > 0 && nx <= n && ny <= n && gridA[nx][ny] <= '9') {
                        int nextId = (nx - 1) * n + ny;
                        if (distPair[startId][nextId] > distPair[startId][cur] + 1 &&
                            distPair[startId][cur] < distZ[x][y]) {
                            distPair[startId][nextId] = distPair[startId][cur] + 1;
                            q.push(nextId);
                        }
                    }
                }
            }
            for (int k = 1; k <= n; k++)
                for (int l = 1; l <= n; l++) {
                    int destId = (k - 1) * n + l;
                    if (distPair[startId][destId] <= min(distZ[k][l], timeLimit))
                        addEdge(startId, destId + 100, 10000);
                }
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            cin >> gridB[i][j];
            if (gridB[i][j] <= '9')
                addEdge((i - 1) * n + j + 100, SNK, gridB[i][j] - '0');
        }
    }

    dinic();
    cout << answer;
    return 0;
}
